^white;공격 배율^reset;: ^green;+10%^reset;
^white;방어력^reset;: ^red;-15%^reset;
    ^#00A9FF;저항^reset;
^white;화염 저항^reset;: ^red;-15%^reset;
^white;전기 저항^reset;: ^red;-15%^reset;
